
/* ============================================================
   Checkpoint 3(續)— 檔案系統、檢視切換、初始化
   ============================================================ */

/* ---------- §12 檔案管理與持久化(Checkpoint 4.1 重寫) ----------
   三層儲存,自動擇優:
   1. window.storage    — claude.ai Artifact 環境專用 API(若存在)
   2. localStorage      — 一般瀏覽器(含直接開啟本機 HTML),重新整理不遺失
   3. 已連結資料夾      — File System Access API(Chrome/Edge):每份使用者文件輸出
      真實 .md 檔 + ekdeta-data.json(使用者文件與完整設定),放在使用者挑選的資料夾
   六份內建文件由目前 HTML 的 SEED_* 每次重建，不進任何持久化層；「恢復原廠」會清空使用者資料並重新載入六份內建文件。 */
const LS_KEY = 'ekdeta';
const FS_OK = typeof window.showDirectoryPicker === 'function';
let dirHandle = null;          // FileSystemDirectoryHandle(連結中的資料夾)
let folderTimer = null, folderBusy = false;

/* 迷你 IndexedDB:只為了跨重新整理保存資料夾 handle */
function idbOpen(){
  return new Promise((res, rej) => {
    const q = indexedDB.open('ekdetaDB', 1);
    q.onupgradeneeded = () => q.result.createObjectStore('kv');
    q.onsuccess = () => res(q.result);
    q.onerror = () => rej(q.error);
  });
}
async function idbSet(k, v){
  try {
    const db = await idbOpen();
    await new Promise((res, rej) => {
      const tx = db.transaction('kv', 'readwrite');
      tx.objectStore('kv').put(v, k);
      tx.oncomplete = res; tx.onerror = () => rej(tx.error);
    });
    db.close();
  } catch(_){}
}
async function idbGet(k){
  try {
    const db = await idbOpen();
    const v = await new Promise((res, rej) => {
      const q = db.transaction('kv').objectStore('kv').get(k);
      q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error);
    });
    db.close();
    return v;
  } catch(_){ return null; }
}

/* 1.1.7.6：REVTeX 版面參數是文件資料，不是應用程式偏好。
   舊版把 settings.revtex* 整包存進 localStorage／備份，造成開 A 論文後再開 B
   論文仍沿用 A 的期刊與版式。現在全域快照排除文件級鍵；每篇 Markdown 最前端
   的 revtex-settings 區塊才是持久化權威。 */
function isRevtexDocumentSettingKey(k){
  return /^revtex[A-Z]/.test(String(k||''));
}
function persistentSettingsSnapshot(){
  const out={};
  let bridgeValues=null;
  try{
    const D=window.__CP171__&&window.__CP171__.registry&&window.__CP171__.registry.revtexDocumentSettings;
    if(D&&typeof D.persistentGlobalValues==='function')bridgeValues=D.persistentGlobalValues();
  }catch(_){}
  for(const k of Object.keys(settings)){
    if(isRevtexDocumentSettingKey(k)||['__proto__','prototype','constructor'].includes(k))continue;
    out[k]=(bridgeValues&&Object.prototype.hasOwnProperty.call(bridgeValues,k))?bridgeValues[k]:settings[k];
  }
  return out;
}
function applyPersistentSettings(raw){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))return;
  for(const k of Object.keys(raw)){
    if(isRevtexDocumentSettingKey(k)||['__proto__','prototype','constructor'].includes(k))continue;
    settings[k]=raw[k];
  }
  /* texBooktabs／texListings 在 REVTEX 工作階段中會被文件暫借。匯入備份時
     仍要更新它們真正的全域值，交由 bridge 在離開模式後恢復。 */
  try{
    const D=window.__CP171__&&window.__CP171__.registry&&window.__CP171__.registry.revtexDocumentSettings;
    if(D&&typeof D.acceptPersistentGlobalValues==='function')D.acceptPersistentGlobalValues(raw);
  }catch(_){}
}
function snapshotData(){
  normalizeUserFonts();   // CP134:任何保存路徑一律寫入九槽位 schema
  normalizeThesisIndentSettings(); // CP160:任何保存路徑只寫入合法縮排模式
  normalizeThemeSettings(); // CP162R3:任何保存路徑只寫入合法主題／dark schema
  return JSON.stringify({ v:2, files:persistentUserFiles(), activeId, settings:persistentSettingsSnapshot() });
}
async function persist(){
  const data = snapshotData();
  try { localStorage.setItem(LS_KEY, data); } catch(_){}
  try { if (window.storage) await window.storage.set(LS_KEY, data); } catch(_){}
  scheduleFolderSync();
}
async function restore(){
  try {
    if (window.storage){
      const r = await window.storage.get(LS_KEY);
      if (r && r.value) return JSON.parse(r.value);
    }
  } catch(_){}
  try {
    const v = localStorage.getItem(LS_KEY);
    if (v) return JSON.parse(v);
  } catch(_){}
  return null;
}
function saveNow(manual){
  const f = activeFile();
  if (f){ f.content = losslessContentForActive('save'); }
  persist();
  if (isBuiltinFile(f)){
    markDirty();
    if (manual) toast(TT('內建文件的修改只保留到切換文件','Built-in document edits last only until you switch files'));
  } else {
    markSaved();
    if (manual) toast(dirHandle ? '已儲存(瀏覽器 + 資料夾)' : '已儲存至瀏覽器');
  }
}
function commitCurrent(){ const f = activeFile(); if (f) f.content = losslessContentForActive('commit'); }

/* ----- 資料夾連結(File System Access API) ----- */
const safeName = n => n.replace(/[\\/:*?"<>|]/g, '_');
async function folderPermOK(h, ask){
  if (!h) return false;
  try {
    if (await h.queryPermission({ mode:'readwrite' }) === 'granted') return true;
    if (ask) return (await h.requestPermission({ mode:'readwrite' })) === 'granted';
  } catch(_){}
  return false;
}
/* CP12:讀取用的權限檢查 — 匯出 PDF 只需要「讀」;readwrite 已授權時
   read 查詢同樣回 granted,故此檢查嚴格寬鬆於舊的 readwrite 查詢。 */
async function readPermOK(h){
  if (!h) return false;
  try { return (await h.queryPermission({ mode:'read' })) === 'granted'; } catch(_){ return false; }
}
/* CP12:趁「使用者手勢」補請求讀取授權。瀏覽器重啟後 FSA 授權會退回
   prompt,而 findFolderFile 只做安靜查詢 — 這正是「連結過資料夾、
   下次匯出 PDF 卻整份佔位框」的根因;匯出入口先呼叫本函式即可喚起授權框。 */
async function ensureReadPerm(h){
  if (!h) return false;
  try {
    if (await h.queryPermission({ mode:'read' }) === 'granted') return true;
    return (await h.requestPermission({ mode:'read' })) === 'granted';
  } catch(_){ return false; }
}
async function writeFolderFile(name, content){
  const fh = await dirHandle.getFileHandle(name, { create:true });
  const w = await fh.createWritable();
  await w.write(content);
  await w.close();
}
async function syncToFolder(){
  if (!dirHandle || folderBusy) return;
  if (!(await folderPermOK(dirHandle, false))) return;   // 無授權時安靜略過(選單可重新授權)
  folderBusy = true;
  try {
    await writeFolderFile('ekdeta-data.json',
      JSON.stringify(JSON.parse(snapshotData()), null, 2));
    for (const f of persistentUserFiles()) await writeFolderFile(safeName(f.name), f.content ?? '');
  } catch(_){} finally { folderBusy = false; }
}
function scheduleFolderSync(){
  if (!dirHandle) return;
  clearTimeout(folderTimer);
  folderTimer = setTimeout(syncToFolder, 2500);
}
async function linkFolder(){
  if (!FS_OK){ toast('此瀏覽器不支援資料夾儲存(需 Chrome / Edge)'); return false; }
  try {
    dirHandle = await showDirectoryPicker({ mode:'readwrite' });
    await idbSet('dir', dirHandle);
    commitCurrent();
    await syncToFolder();
    toast('已連結資料夾「' + dirHandle.name + '」,將自動同步');
    buildMenubar();
    return true;
  } catch(e){
    if (e && e.name !== 'AbortError') toast('連結失敗:' + e.message);
    return false;
  }
}
async function unlinkFolder(){
  dirHandle = null;
  await idbSet('dir', null);
  toast('已中斷資料夾連結(瀏覽器內資料保留)');
  buildMenubar();
}
async function loadFromFolder(){
  if (!FS_OK){ toast('此瀏覽器不支援資料夾儲存(需 Chrome / Edge)'); return; }
  if (!dirHandle) dirHandle = await idbGet('dir');
  if (!dirHandle){ toast('尚未連結資料夾,請先使用「連結儲存資料夾…」'); return; }
  if (!(await folderPermOK(dirHandle, true))){ toast('未取得資料夾授權'); return; }
  try {
    const fh = await dirHandle.getFileHandle('ekdeta-data.json');
    const data = JSON.parse(await (await fh.getFile()).text());
    if (!data || !Array.isArray(data.files)) throw new Error('格式不符');
    applyPersistentSettings(data.settings || {});
    normalizeUserFonts();
    normalizeThesisIndentSettings();
    applyThemeFromSettings();
    applyThesisIndentSettings();
    files = normalizeFilesWithBuiltins(data.files, data.v !== 2);
    fbOptsApply();
    losslessResetAll();   /* CP73:外部 findOpts 淨化+三鈕同步(switchFile 尾以新選項重算) */
    activeId = null;
    switchFile(files.some(f => f.id === data.activeId) ? data.activeId : files[0].id);
    persist();
    toast(TT('已從資料夾載入 ','Loaded ') + userFileCount() + TT(' 份使用者文件',' user documents from folder'));
  } catch(_){
    toast('資料夾內找不到有效的 ekdeta-data.json');
  }
}

/* ----- 圖片解析:相對路徑 → 已連結資料夾(§6) -----
   瀏覽器安全模型不允許網頁任意讀本機檔;若已「連結儲存資料夾」,
   圖片載入失敗時自動在該資料夾內依相對路徑尋找並以 ObjectURL 顯示。 */
const imgURLCache = new Map();
/* 共用:在已連結資料夾中依相對路徑找檔(逐層剝前綴 → 純檔名 → 獨立圖片資料夾)。
   回傳 File 或 null。渲染解析與 PDF 匯出共用同一套邏輯。 */
async function findFolderFile(path){
  let p = String(path || '');
  try { p = decodeURIComponent(p); } catch(_){}
  p = p.replace(/^file:\/\//i, '').replace(/^\.\//, '').replace(/^\//, '');
  const parts = p.split('/').filter(Boolean);
  if (!parts.length) return null;
  if (dirHandle && await readPermOK(dirHandle)){
    for (let start = 0; start < parts.length; start++){
      try {
        let dir = dirHandle;
        for (let k = start; k < parts.length - 1; k++)
          dir = await dir.getDirectoryHandle(parts[k]);
        const fh = await dir.getFileHandle(parts[parts.length - 1]);
        return await fh.getFile();
      } catch(_){ /* 換下一層繼續找 */ }
    }
  }
  try {
    if (imgDirHandle && await readPermOK(imgDirHandle)){
      const fh = await imgDirHandle.getFileHandle(parts[parts.length - 1]);
      return await fh.getFile();
    }
  } catch(_){}
  return findPickedFile(path);   // CP12:webkitdirectory 備援清單(§6c)
}
/* CP14:圖片載入失敗一律嘗試就地復原,失敗則記入「待修復」並顯示修復橫幅。
   關鍵改動:不再因「尚未連結任何資料夾」就靜默 return —— file:// 雙擊開檔、
   圖檔被移動/改名/被雲端同步驅逐時,原生相對路徑載入會失敗且無授權可查,
   舊版於此無聲放棄。現在改為:失敗即標記壞圖 + 亮出橫幅,一鍵選圖片資料夾
   (webkitdirectory,全瀏覽器與 file:// 皆可),以 File 位元組產生 ObjectURL 復原。 */
const brokenImgs = new Set();
async function resolveImgFromFolder(img){
  if (img.dataset.folderTried) return;
  const p = img.getAttribute('src') || '';
  if (/^(data:|blob:)/i.test(p)) return;                   // 內嵌 / 記憶體圖:與本機檔無關
  img.dataset.folderTried = '1';
  const key = p.replace(/^file:\/\//i, '').replace(/^\.\//, '').replace(/^\//, '');
  img.dataset.osrc = key;                                  // 保留原始路徑(PDF 匯出用)
  if (imgURLCache.has(key)){ img.src = imgURLCache.get(key); markImgOK(img); return; }
  let file = null;
  try { file = await findFolderFile(key); } catch(_){}
  if (file){
    const url = URL.createObjectURL(file);
    imgURLCache.set(key, url);
    img.src = url; markImgOK(img);
  } else if (!/^https?:/i.test(p)){                        // 本機圖取不到 → 待修復
    markImgBroken(img);
  }
}
function markImgOK(img){
  img.classList.remove('img-broken');
  brokenImgs.delete(img);
  updateImgFixBar();
}
function markImgBroken(img){
  img.classList.add('img-broken');
  if (!img.getAttribute('alt')) img.setAttribute('alt', '圖片無法載入:' + (img.dataset.osrc || ''));
  brokenImgs.add(img);
  updateImgFixBar();
}
/* CP126-DIAG4：缺圖警告不只報數量，也提供可操作的逐檔診斷清單。
   不依賴 PDF clone／分頁座標；頁碼只從目前 paper-bg 的實際 sheet rect 判定，
   普通 Markdown 模式則回報 block 序號。相同路徑的多次引用會合併，但保留引用數。 */
function missingImagePage(im){
  if (!inPaperMode()) return 0;
  const bg = $('#paper-bg');
  const sheets = bg ? [...bg.children] : [];
  if (!sheets.length) return 0;
  const r = im.getBoundingClientRect();
  const y = r.top + Math.max(.5, r.height / 2);
  let nearest = 0, best = Infinity;
  for (let i = 0; i < sheets.length; i++){
    const sr = sheets[i].getBoundingClientRect();
    if (y >= sr.top - 1 && y <= sr.bottom + 1) return i + 1;
    const d = y < sr.top ? sr.top - y : y - sr.bottom;
    if (d < best){ best = d; nearest = i + 1; }
  }
  return nearest;
}
/* Cheap image state shared by the notice and detailed diagnostics.
 * Only the detailed list reads block/page geometry. Preserve DOM order and
 * occurrence numbers, including loaded and remote images between failures. */
function collectUnresolvedLocalImages(){
  return [...editor.querySelectorAll('img')].map((im, occurrence) => {
    const shownSrc = im.getAttribute('src') || '';
    const raw = (/^(?:data:|blob:)/i.test(shownSrc) ? (im.dataset.osrc || shownSrc) : shownSrc) || im.dataset.osrc || '';
    const local = !!raw && !/^(?:data:|blob:|https?:)/i.test(raw);
    const missing = im.classList.contains('img-broken') || !im.complete || !(im.naturalWidth > 0);
    return local && missing ? { im, raw, occurrence:occurrence + 1 } : null;
  }).filter(Boolean);
}
function unresolvedLocalImages(){
  const children = [...editor.children];
  return collectUnresolvedLocalImages().map(({ im, raw, occurrence }) => {
    let path = raw;
    try { path = decodeURIComponent(path); } catch(_){ }
    path = path.replace(/^file:\/\//i, '').replace(/\\/g, '/');
    const block = im.closest('.block');
    return { im, path:path || TT('(路徑空白)','(empty path)'), alt:im.getAttribute('alt') || '',
             occurrence, block:Math.max(0, children.indexOf(block)) + 1,
             page:missingImagePage(im) };
  });
}
function missingImageGroups(){
  const map = new Map();
  for (const row of unresolvedLocalImages()){
    const key = row.path.toLowerCase();
    let g = map.get(key);
    if (!g){ g = { path:row.path, rows:[], pages:new Set(), blocks:new Set(), alts:new Set() }; map.set(key, g); }
    g.rows.push(row);
    if (row.page) g.pages.add(row.page);
    if (row.block) g.blocks.add(row.block);
    if (row.alt) g.alts.add(row.alt);
  }
  return [...map.values()];
}
function showMissingImageList(){
  const groups = missingImageGroups();
  if (!groups.length){ toast(TT('目前沒有缺少的本機圖片','No local images are currently missing')); return; }
  const refs = groups.reduce((n, g) => n + g.rows.length, 0);
  const items = groups.map((g, i) => {
    const pages = [...g.pages].sort((a,b) => a-b);
    const blocks = [...g.blocks].sort((a,b) => a-b);
    const where = pages.length
      ? TT(`頁面：${pages.join('、')}`, `Page(s): ${pages.join(', ')}`)
      : TT(`區塊：${blocks.join('、')}`, `Block(s): ${blocks.join(', ')}`);
    const alt = [...g.alts].slice(0, 2).join('／');
    return `<li style="margin:0 0 12px;line-height:1.55"><button type="button" class="missing-img-jump fb-btn txt" data-mi="${i}" ` +
      `style="display:block;width:100%;text-align:left;padding:8px 10px;overflow-wrap:anywhere;color:var(--text);background:var(--bg);border:1px solid var(--border)"><b>${escapeHtml(g.path)}</b>` +
      `<br><span style="font-size:12px;opacity:.78">${escapeHtml(where)}${g.rows.length > 1 ? ` · ${TT('引用','References')}: ${g.rows.length}` : ''}` +
      `${alt ? ' · alt: ' + escapeHtml(alt) : ''}</span></button></li>`;
  }).join('');
  showModal(`<h2>${TT('缺少的圖片','Missing images')}</h2>` +
    `<p style="font-size:13px;line-height:1.75">${TT(`共有 ${refs} 個缺圖引用，涉及 ${groups.length} 個檔案。點擊項目可跳到文件中的第一個位置。`,
      `${refs} missing image reference(s), covering ${groups.length} file(s). Select an item to jump to its first occurrence.`)}</p>` +
    `<div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 14px">` +
    `<button id="missing-img-copy" type="button" class="fb-btn txt" style="padding:6px 12px;color:var(--text);background:var(--bg);border:1px solid var(--border-strong)">${TT('複製路徑清單','Copy path list')}</button>` +
    `<button id="missing-img-pick" type="button" class="fb-btn txt" style="padding:6px 12px;color:var(--text);background:var(--bg);border:1px solid var(--border-strong)"><b>${TT('選擇圖片資料夾修復…','Choose image folder to fix…')}</b></button></div>` +
    `<ol style="padding-left:22px;max-height:52vh;overflow:auto;margin:0">${items}</ol>`);
  document.querySelectorAll('.missing-img-jump').forEach(btn => btn.addEventListener('click', () => {
    const g = groups[+(btn.dataset.mi || 0)], row = g && g.rows[0];
    hideModal();
    if (row && row.im && row.im.isConnected){
      row.im.scrollIntoView({ block:'center', behavior:'smooth' });
      if (row.im.animate){
        row.im.animate([{outline:'4px solid #ffcc66'},{outline:'0 solid transparent'}], {duration:1400,easing:'ease-out'});
      } else {
        row.im.style.outline = '4px solid #ffcc66';
        setTimeout(() => { if (row.im) row.im.style.outline = ''; }, 1400);
      }
    }
  }));
  $('#missing-img-pick').onclick = () => { hideModal(); pickPdfImgFallback(); };
  $('#missing-img-copy').onclick = async () => {
    const text = groups.map(g => g.path).join('\n');
    let ok = false;
    try { await navigator.clipboard.writeText(text); ok = true; } catch(_){ }
    if (!ok){
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.cssText = 'position:fixed;left:-9999px';
      document.body.appendChild(ta); ta.select();
      try { ok = document.execCommand('copy'); } catch(_){ }
      ta.remove();
    }
    toast(ok ? TT('已複製缺圖路徑清單','Missing-image paths copied') : TT('無法自動複製，請手動選取清單','Could not copy automatically'));
  };
}
function updateImgFixBar(){
  const bar = $('#img-fix-bar');
  const rows = collectUnresolvedLocalImages();
  const unresolved = new Set(rows.map(row => row.im));
  for (const im of [...brokenImgs]) if (!im.isConnected || !unresolved.has(im)) brokenImgs.delete(im);
  rows.forEach(row => brokenImgs.add(row.im));
  const n = rows.length;
  if (n > 0){
    $('#img-fix-msg').textContent = isEN()
      ? `${n} local image(s) failed to load (files may have been moved, renamed, or evicted by cloud sync).`
      : `有 ${n} 張本機圖片無法載入(檔案可能被移動、改名或雲端同步移除)。`;
    bar.classList.add('show');
  } else bar.classList.remove('show');
}
/* 選好圖片資料夾後,主動重解析所有壞圖(不必等再次 error) */
function reResolveBrokenImgs(){
  editor.querySelectorAll('img').forEach(im => {
    if (!im.complete || im.naturalWidth === 0 || im.classList.contains('img-broken')){
      delete im.dataset.folderTried;
      resolveImgFromFolder(im);
    }
  });
}
$('#img-fix-btn').addEventListener('click', () => pickPdfImgFallback());
$('#img-fix-list').addEventListener('click', showMissingImageList);
$('#img-fix-close').addEventListener('click', () => $('#img-fix-bar').classList.remove('show'));
$('#tpl-copy-btn').addEventListener('click', () => createFromTemplate());   /* CP112 */
editor.addEventListener('load', e => {
  if (e.target && e.target.tagName === 'IMG') markImgOK(e.target);
}, true);
editor.addEventListener('error', e => {
  if (e.target && e.target.tagName === 'IMG') resolveImgFromFolder(e.target);
}, true);

/* ---- §6c PDF 圖片備援來源(CP12) ----
   以 file:// 直開本檔時,瀏覽器「顯示」本機圖片沒有問題,但畫布讀取
   一律被汙染 → 匯出引擎拿不到位元組,這就是佔位框的成因。FSA 連結
   資料夾只有 Chrome / Edge 支援,因此補上全瀏覽器(含 Safari / Firefox)
   通用的備援:<input webkitdirectory> 一次選取圖片所在資料夾,取得
   File 物件清單直讀位元組;findFolderFile 在 FSA 找不到時自動改查這份清單。 */
let pdfImgFiles = null;          // Map<相對路徑(小寫), File> — 本瀏覽階段有效
let pdfImgPickResolve = null;    // askPdfImgDir 等待選取結果的回呼
$('#pdf-imgdir').addEventListener('change', e => {
  const list = [...(e.target.files || [])];
  e.target.value = '';                              // 允許重選同一資料夾
  const cb = pdfImgPickResolve; pdfImgPickResolve = null;
  if (!list.length){ if (cb) cb(false); return; }
  pdfImgFiles = new Map();
  for (const f of list)
    pdfImgFiles.set((f.webkitRelativePath || f.name).toLowerCase(), f);
  editor.querySelectorAll('img').forEach(im => delete im.dataset.folderTried);
  toast('已載入圖片資料夾(' + pdfImgFiles.size + ' 個檔案)');
  reResolveBrokenImgs();                              // CP14:主動修復編輯畫面的壞圖
  if (cb) cb(true);
});
$('#pdf-imgdir').addEventListener('cancel', () => {  // 使用者關閉了選取視窗
  const cb = pdfImgPickResolve; pdfImgPickResolve = null;
  if (cb) cb(false);
});
/* 在已選清單中依「路徑尾碼由長到短」找檔:
   src=image/a.png 可命中 webkitRelativePath=論文/image/a.png 或 image/a.png,
   絕對路徑(/Users/…/image/a.png)則逐層剝前綴後同樣能對上。 */
function findPickedFile(path){
  if (!pdfImgFiles || !pdfImgFiles.size) return null;
  let p = String(path || '');
  try { p = decodeURIComponent(p); } catch(_){}
  p = p.replace(/^file:\/\//i, '').replace(/\\/g, '/').toLowerCase();
  const parts = p.split('/').filter(x => x && x !== '.');
  for (let start = 0; start < parts.length; start++){
    const suf = parts.slice(start).join('/');
    for (const [rel, f] of pdfImgFiles)
      if (rel === suf || rel.endsWith('/' + suf)) return f;
  }
  return null;
}
function pickPdfImgFallback(){ $('#pdf-imgdir').click(); }
/* 匯出途中發現本機圖片取不到位圖 → 徵詢使用者。
   回傳 'picked'(已選資料夾)| 'skip'(以佔位框匯出)| 'cancel'。 */
function askPdfImgDir(n){
  return new Promise(res => {
    let settled = false;
    const ov = $('#modal-overlay');
    const mo = new MutationObserver(() => {           // Esc / 點遮罩關閉 → 視同取消
      if (!ov.classList.contains('show')) done('cancel');
    });
    const done = v => {
      if (settled) return;
      settled = true; mo.disconnect(); pdfImgPickResolve = null;
      hideModal(); res(v);
    };
    showModal(isEN() ? `<h2>Embed images into PDF</h2>
      <p style="font-size:13.5px;line-height:1.9"><b>${n}</b> local image(s) can't be read directly by the
      engine due to browser security (they display fine, but embedding into PDF needs the raw bytes).<br>
      Please choose the <b>folder that contains the images</b> — the whole document folder is fine, it searches inward automatically.</p>
      <div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap">
        <button id="pim-pick" class="fb-btn txt" style="padding:7px 14px"><b>Choose image folder…</b></button>
        <button id="pim-skip" class="fb-btn txt" style="padding:7px 14px">Export with placeholders</button>
        <button id="pim-cancel" class="fb-btn txt" style="padding:7px 14px">Cancel</button>
      </div>` : `<h2>嵌入圖片到 PDF</h2>
      <p style="font-size:13.5px;line-height:1.9">有 <b>${n}</b> 張本機圖片因瀏覽器安全限制,
      引擎無法直接讀取檔案本體(畫面顯示正常,但嵌入 PDF 需要原始位元組)。<br>
      請選取<b>圖片所在的資料夾</b> — 選整個文件資料夾也可以,會自動往內尋找。</p>
      <div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap">
        <button id="pim-pick" class="fb-btn txt" style="padding:7px 14px"><b>選擇圖片資料夾…</b></button>
        <button id="pim-skip" class="fb-btn txt" style="padding:7px 14px">以佔位框匯出</button>
        <button id="pim-cancel" class="fb-btn txt" style="padding:7px 14px">取消</button>
      </div>`);
    $('#modal-close').style.display = 'none';
    mo.observe(ov, { attributes: true, attributeFilter: ['class'] });
    $('#pim-pick').onclick = () => {
      pdfImgPickResolve = ok => done(ok ? 'picked' : 'cancel');
      $('#pdf-imgdir').click();
    };
    $('#pim-skip').onclick = () => done('skip');
    $('#pim-cancel').onclick = () => done('cancel');
  });
}

/* ----- 圖片貼上 / 拖放(Checkpoint 6) -----
   沿用一般編輯器操作:貼上剪貼簿圖片或拖入圖片檔 → 自動存檔並插入 Markdown 連結。
   儲存位置依偏好設定:獨立圖片資料夾 → 儲存資料夾的子資料夾(預設 image/)
   → 內嵌 base64(未連結任何資料夾時的備援)。 */
let imgDirHandle = null;   // 偏好設定中「另外指定的圖片資料夾」

function cleanImageSubfolder(value){
  let v = String(value == null ? '' : value).trim().replace(/\\/g,'/');
  v = v.replace(/^(?:\.\/|\/)+|\/+$/g,'');
  const parts = v.split('/').map(x => safeName(x.trim())).filter(x => x && x !== '.' && x !== '..');
  return parts.join('/') || 'image';
}
async function ensureImageSubfolder(root, relativePath){
  let dir = root;
  for (const part of cleanImageSubfolder(relativePath).split('/'))
    dir = await dir.getDirectoryHandle(part, { create:true });
  return dir;
}
function cleanImageLinkPrefix(value){
  let v = String(value == null ? '' : value).trim();
  if (!v) return '';
  v = v.replace(/\\/g,'/');
  return v.replace(/\/+$/,'');
}
function imageLinkJoin(prefix, name){
  const p = cleanImageLinkPrefix(prefix);
  return p ? p + '/' + name : name;
}
async function pickedImageMarkdownPath(name){
  const explicit = cleanImageLinkPrefix(settings.imgPickedLink);
  if (explicit) return imageLinkJoin(explicit, name);
  /* 同一個已連結專案根目錄內時，File System Access API 可推導真正相對路徑。 */
  if (dirHandle && imgDirHandle && typeof dirHandle.resolve === 'function'){
    try {
      const parts = await dirHandle.resolve(imgDirHandle);
      if (Array.isArray(parts)) return './' + parts.concat(name).join('/');
    } catch(_){ /* 不同根目錄／瀏覽器不支援 → 回到檔名或使用者指定前綴 */ }
  }
  return name;
}
function storageFolderLabel(){ return dirHandle ? dirHandle.name : ''; }
function storageImageLogicalPath(){ return './' + cleanImageSubfolder(settings.imgSub) + '/'; }

async function pickImgDir(){
  if (!FS_OK){ toast('此瀏覽器不支援資料夾(需 Chrome / Edge)'); return false; }
  try {
    imgDirHandle = await showDirectoryPicker({ mode:'readwrite' });
    await idbSet('imgdir', imgDirHandle);
    settings.imgMode = 'picked';
    persist();
    toast('圖片將存到「' + imgDirHandle.name + '」');
    return true;
  } catch(e){ if (e && e.name !== 'AbortError') toast('選擇失敗:' + e.message); return false; }
}
async function saveImageBlob(file){
  const ext = (((file.type || '').split('/')[1] || 'png').replace('jpeg', 'jpg')
               .replace(/[^a-z0-9]/gi, '')) || 'png';
  const name = 'img-' + Date.now().toString(36) +
               Math.random().toString(36).slice(2, 5) + '.' + ext;
  const put = async (dir, path) => {
    const fh = await dir.getFileHandle(name, { create: true });
    const w = await fh.createWritable();
    await w.write(file); await w.close();
    imgURLCache.set(path.replace(/^\.\//, ''), URL.createObjectURL(file));  // 立即可顯示
    return path;
  };
  try {
    if (settings.imgMode === 'picked' && imgDirHandle && await folderPermOK(imgDirHandle, true))
      return await put(imgDirHandle, await pickedImageMarkdownPath(name));
    if (settings.imgMode !== 'embed' && dirHandle && await folderPermOK(dirHandle, true)){
      const sub = cleanImageSubfolder(settings.imgSub);
      const dir = await ensureImageSubfolder(dirHandle, sub);
      return await put(dir, './' + sub + '/' + name);
    }
  } catch(_){ /* 落地失敗 → 走內嵌備援 */ }
  if (file.size > 1.5 * 1024 * 1024){
    toast('圖片超過 1.5MB:請先於檔案選單「連結儲存資料夾」再貼上');
    return null;
  }
  const dataURL = await new Promise(res => {
    const r = new FileReader();
    r.onload = () => res(String(r.result));
    r.onerror = () => res(null);
    r.readAsDataURL(file);
  });
  if (dataURL && settings.imgMode !== 'embed')
    toast('未連結資料夾:圖片以內嵌方式插入(建議連結資料夾存成檔案)');
  return dataURL;
}
function insertImageMD(path, altHint){
  const md = `![${(altHint || '').replace(/[\[\]\n]/g, '')}](${path})`;
  if (tableEdit){
    document.execCommand('insertText', false, md);
    syncTableFromDOM(); onEdited();
    return;
  }
  if (activeIndex >= 0){
    pushUndo();
    insertTextAtCaret(md);
    onEdited();
    return;
  }
  pushUndo();                                   // 無啟用區塊 → 附加到文件尾
  blocks.push(md);
  const el = document.createElement('div');
  el.className = 'block';
  el.innerHTML = renderBlockHTML(md);
  editor.appendChild(el);
  onEdited();
  el.scrollIntoView({ block: 'center' });
}
async function handleImageFiles(fileList, altBase){
  const arr = [...fileList].filter(f => f && /^image\//.test(f.type));
  if (!arr.length) return;
  for (const f of arr){
    const p = await saveImageBlob(f);
    if (p) insertImageMD(p, (f.name || altBase || '').replace(/\.[a-z0-9]+$/i, '') || altBase);
  }
}

/* ----- 偏好設定 ----- */
/* ============================================================
   CP134(0.9.114)— 九槽位、多語系／字集路由的自訂字體
   ・一般 Markdown：Latin／中文；A4 Paper：Latin／中文；
     TW_THESIS 中文版：Latin／中文；TW_THESIS English：Latin／中文 fallback；程式碼：mono。
   ・舊 CP27 settings.userFonts{body,paper,twthesis,mono} 於載入時自動遷移；
     twthesis 舊值同時進中、英文 Latin 槽，維持舊版「兩主題一起套用」的行為。
   ・Latin 與 CJK 透過動態 @font-face + unicode-range 各自路由，即使中文
     字體本身含 Latin glyph，也不會吃掉使用者另設的英文字體。
   ・CSS 變數仍 inline 掛在 #editor，PDF clone 可完整繼承；動態路由樣式
     由 buildPdfCSS() 額外注入，螢幕與向量 PDF 共用同一條字體鏈。
   ============================================================ */
const USER_FONT_DEFAULTS = Object.freeze({
  body:'-apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang TC", "Helvetica Neue", "Open Sans", sans-serif',
  paper:'"Times New Roman","Georgia","Songti TC","Songti SC","Noto Serif TC","Noto Serif CJK TC","Source Han Serif TC","Source Han Serif TW","STSong","Apple LiSung","LiSong Pro","PMingLiU","MingLiU","SimSun",serif',
  twthesisZh:'"Palatino Linotype","Book Antiqua","Palatino","URW Palladio L","TeX Gyre Pagella","P052","Tinos","Times New Roman","Times","DFKai-SB","標楷體","BiauKai","Kaiti TC","Kaiti SC","STKaiti","KaiTi","AR PL UKai TW","AR PL KaitiM Big5","Noto Serif TC","Noto Serif CJK TC","Source Han Serif TC","Source Han Serif TW","Songti TC","PMingLiU","MingLiU",serif',
  twthesisEn:'"TW_THESIS Pagella Local","TW_THESIS Pagella Embedded","Palatino Linotype","Book Antiqua","Palatino","URW Palladio L","TeX Gyre Pagella","P052","Tinos","Times New Roman","Times","Songti TC","Songti SC","Noto Serif TC","Noto Serif CJK TC","Source Han Serif TC","Source Han Serif TW","STSong","Apple LiSung","LiSong Pro","PMingLiU","MingLiU","SimSun",serif',
  mono:'"JetBrains Mono", "SF Mono", ui-monospace, Menlo, Consolas, "Liberation Mono", "PingFang TC", "Microsoft JhengHei", monospace',
});
const USER_FONT_RANGES = Object.freeze({
  latin:'U+0000-024F,U+1E00-1EFF,U+2000-206F,U+20A0-20CF,U+2100-214F,U+2150-218F,U+2190-22FF,U+FB00-FB06',
  cjk:'U+2E80-2FFF,U+3000-303F,U+3040-30FF,U+3100-312F,U+31A0-31EF,U+3200-32FF,U+3400-4DBF,U+4E00-9FFF,U+F900-FAFF,U+FF00-FFEF,U+20000-2FA1F',
});
const USER_FONT_SLOTS = [
  { key:'bodyLatin', target:'body',  script:'latin', alias:'Ekdeta Body Latin' },
  { key:'bodyCjk',   target:'body',  script:'cjk',   alias:'Ekdeta Body CJK' },
  { key:'paperLatin',target:'paper', script:'latin', alias:'Ekdeta Paper Latin' },
  { key:'paperCjk',  target:'paper', script:'cjk',   alias:'Ekdeta Paper CJK' },
  { key:'twthesisZhLatin',target:'twthesisZh', script:'latin', alias:'Ekdeta TW_THESIS ZH Latin' },
  { key:'twthesisZhCjk',  target:'twthesisZh', script:'cjk',   alias:'Ekdeta TW_THESIS ZH CJK' },
  { key:'twthesisEnLatin',target:'twthesisEn', script:'latin', alias:'Ekdeta TW_THESIS EN Latin' },
  { key:'twthesisEnCjk',  target:'twthesisEn', script:'cjk',   alias:'Ekdeta TW_THESIS EN CJK' },
  { key:'mono',      target:'mono',  script:'mono',  alias:'Ekdeta User Mono' },
];
const USER_FONT_TARGETS = Object.freeze({
  body: { cssVar:'--font-body',  keys:['bodyLatin','bodyCjk'],   def:USER_FONT_DEFAULTS.body },
  paper:{ cssVar:'--paper-font', keys:['paperLatin','paperCjk'], def:USER_FONT_DEFAULTS.paper },
  twthesisZh:{ cssVar:'--twthesis-font',   keys:['twthesisZhLatin','twthesisZhCjk'], def:USER_FONT_DEFAULTS.twthesisZh },
  twthesisEn:{ cssVar:'--twthesis-font',   keys:['twthesisEnLatin','twthesisEnCjk'], def:USER_FONT_DEFAULTS.twthesisEn },
  mono: { cssVar:'--font-mono',  keys:['mono'],                  def:USER_FONT_DEFAULTS.mono },
});
const USER_FONT_KEYS = USER_FONT_SLOTS.map(s => s.key);
function emptyUserFonts(){
  const out = {};
  USER_FONT_KEYS.forEach(k => { out[k] = ''; });
  return out;
}
function cleanFontSetting(v){ return typeof v === 'string' ? v.trim() : ''; }
function normalizeUserFonts(){
  const raw = settings.userFonts && typeof settings.userFonts === 'object' ? settings.userFonts : {};
  const next = emptyUserFonts();
  next.bodyLatin = cleanFontSetting(raw.bodyLatin != null ? raw.bodyLatin : raw.body);
  next.bodyCjk = cleanFontSetting(raw.bodyCjk);
  next.paperLatin = cleanFontSetting(raw.paperLatin != null ? raw.paperLatin : raw.paper);
  next.paperCjk = cleanFontSetting(raw.paperCjk);
  /* CP27 的 twthesis 同時控制中／英文；遷移時兩個 Latin 槽都承接，行為不縮水。 */
  next.twthesisZhLatin = cleanFontSetting(raw.twthesisZhLatin != null ? raw.twthesisZhLatin : raw.twthesis);
  next.twthesisZhCjk = cleanFontSetting(raw.twthesisZhCjk);
  next.twthesisEnLatin = cleanFontSetting(raw.twthesisEnLatin != null ? raw.twthesisEnLatin : raw.twthesis);
  next.twthesisEnCjk = cleanFontSetting(raw.twthesisEnCjk);
  next.mono = cleanFontSetting(raw.mono);
  const before = JSON.stringify(raw), after = JSON.stringify(next);
  settings.userFonts = next;
  const toolbarChanged = typeof normalizeToolbarItems === 'function' ? normalizeToolbarItems() : false;
  const logoChanged = typeof normalizeTwThesisLogoChoice === 'function' ? normalizeTwThesisLogoChoice() : false;
  const logoScaleChanged = typeof normalizeTwThesisLogoScale === 'function' ? normalizeTwThesisLogoScale() : false;
  const oldLink = settings.imgPickedLink, oldSub = settings.imgSub;
  settings.imgPickedLink = cleanImageLinkPrefix(settings.imgPickedLink);
  settings.imgSub = cleanImageSubfolder(settings.imgSub);
  return before !== after || toolbarChanged || logoChanged || logoScaleChanged || oldLink !== settings.imgPickedLink || oldSub !== settings.imgSub;
}
function userFontSlot(key){ return USER_FONT_SLOTS.find(s => s.key === key) || null; }
function cssFontName(n){
  n = String(n || '').trim().replace(/["']/g, '');
  return /[^A-Za-z0-9\-]/.test(n) ? '"' + n + '"' : n;
}
function cssFontString(n){
  return '"' + String(n || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
function ensureUserFontRoutingStyle(){
  let style = document.getElementById('user-font-routing');
  if (!style){ style = document.createElement('style'); style.id = 'user-font-routing'; document.head.appendChild(style); }
  const uf = settings.userFonts || {};
  const rules = [];
  for (const slot of USER_FONT_SLOTS){
    const value = cleanFontSetting(uf[slot.key]);
    if (!value) continue;
    const range = slot.script === 'mono' ? '' : 'unicode-range:' + USER_FONT_RANGES[slot.script] + ';';
    rules.push('@font-face{font-family:' + cssFontString(slot.alias) + ';src:local(' + cssFontString(value) + ');' +
      'font-style:normal;font-weight:100 900;font-display:swap;' + range + '}');
  }
  style.textContent = rules.join('\n');
  return style;
}
function userFontTargetStack(target){
  const uf = settings.userFonts || {}, cfg = USER_FONT_TARGETS[target];
  const aliases = cfg.keys.filter(k => cleanFontSetting(uf[k])).map(k => cssFontString(userFontSlot(k).alias));
  return aliases.length ? aliases.join(', ') + ', ' + cfg.def : '';
}
/* 冪等；applyTheme / 啟動 / 還原備份 / 偏好設定變更都會呼叫。 */
function applyUserFonts(){
  normalizeUserFonts();
  ensureUserFontRoutingStyle();
  for (const target of ['body','paper','mono']){
    const cfg = USER_FONT_TARGETS[target], stack = userFontTargetStack(target);
    if (stack) editor.style.setProperty(cfg.cssVar, stack); else editor.style.removeProperty(cfg.cssVar);
  }
  const twthesisTarget = isTwThesisEnglishTheme() ? 'twthesisEn' : 'twthesisZh';
  const twthesisStack = userFontTargetStack(twthesisTarget);
  if (twthesisStack){
    editor.style.setProperty('--twthesis-font', twthesisStack);
    document.body.style.setProperty('--twthesis-font', twthesisStack);   /* 紙張背景頁碼／running head 亦即時同步 */
  } else {
    editor.style.removeProperty('--twthesis-font');
    document.body.style.removeProperty('--twthesis-font');
  }
  /* 1.1.7.5：Source Mode 的真輸入層、可見鏡像與行號 gutter 必須
     從同一個幾何擁有者繼承 --font-mono。只把字體掛在透明 textarea，會讓
     長行在不同 glyph advance 下累積 soft-wrap 高度差。 */
  const sourceFontOwner = document.getElementById('src-shell');
  const sourceView = document.getElementById('srcview');
  const sourceMirror = document.getElementById('src-highlight');
  const monoStack = userFontTargetStack('mono');
  if (sourceFontOwner){
    if (monoStack) sourceFontOwner.style.setProperty('--font-mono', monoStack);
    else sourceFontOwner.style.removeProperty('--font-mono');
    sourceView?.style.removeProperty('--font-mono');
    sourceMirror?.style.removeProperty('--font-mono');
  } else {
    /* 防禦性 fallback：未來 DOM 改名時仍不允許 input 與 mirror 字體分叉。 */
    for (const el of [sourceView, sourceMirror]){
      if (!el) continue;
      if (monoStack) el.style.setProperty('--font-mono', monoStack);
      else el.style.removeProperty('--font-mono');
    }
  }
  if (settings.srcmode && sourceView && sourceMirror){
    srcRenderDecorations();
    if (typeof srcTrackLayout === 'function') srcTrackLayout(180);
    else if (typeof srcSyncMirrorGeometry === 'function') srcSyncMirrorGeometry(true);
    if (document.fonts?.ready?.then){
      document.fonts.ready.then(() => {
        if (!settings.srcmode || !sourceView.isConnected || !sourceMirror.isConnected) return;
        srcRenderDecorations();
        if (typeof srcTrackLayout === 'function') srcTrackLayout(96);
        else if (typeof srcSyncMirrorGeometry === 'function') srcSyncMirrorGeometry(true);
      }).catch(() => {});
    }
  }
}
/* 常見字體偵測:canvas 量測寬度,與三個 generic fallback 任一不同即視為已安裝 */
const FONT_CANDIDATES = [
  'Arial','Arial Narrow','Helvetica','Helvetica Neue','Verdana','Tahoma','Trebuchet MS','Segoe UI',
  'Calibri','Cambria','Candara','Constantia','Corbel','Georgia','Times New Roman','Times',
  'Palatino','Palatino Linotype','Book Antiqua','Garamond','Baskerville','Didot','Optima','Futura',
  'Avenir','Avenir Next','Gill Sans','Rockwell','American Typewriter','Charter','Inter','Roboto',
  'Open Sans','Lato','Montserrat','Source Sans Pro','Noto Sans','Noto Serif','Comic Sans MS','Impact',
  'Courier New','Courier','Menlo','Monaco','Consolas','SF Mono','Cascadia Code','Fira Code',
  'Source Code Pro','Roboto Mono','Ubuntu Mono','IBM Plex Mono',
  'PingFang TC','PingFang SC','Heiti TC','Songti TC','Songti SC','Kaiti TC','BiauKai','DFKai-SB',
  'Microsoft JhengHei','Microsoft YaHei','MingLiU','PMingLiU','SimSun','SimHei','KaiTi','FangSong',
  'STHeiti','STKaiti','STSong','STFangsong','Apple LiGothic','Apple LiSung','LiHei Pro','LiSong Pro',
  'Hiragino Sans','Hiragino Mincho ProN','Hiragino Sans GB','Yu Gothic','Yu Mincho','Meiryo',
  'Noto Sans TC','Source Han Sans TC','Source Han Serif TC',
  '標楷體', 'Noto Serif TC', 'Noto Serif CJK TC', 'Source Han Serif TW', 'AR PL UKai TW', 'AR PL KaitiM Big5',
];
let _fontListCache = null;
function availableFontList(){
  if (_fontListCache) return _fontListCache;
  const embedded = ['JetBrains Mono', 'TW_THESIS Pagella Embedded', 'TW_THESIS Pagella Local', 'TW_THESIS Euler Embedded'];   /* CP134:內嵌論文字體亦列於清單頂 */
  const cv = document.createElement('canvas'), cx = cv.getContext('2d');
  const S = 'mmmmMMwwil10O永體測試字あア한';
  const bases = ['monospace', 'serif', 'sans-serif'];
  const bw = {};
  for (const b of bases){ cx.font = '72px ' + b; bw[b] = cx.measureText(S).width; }
  const ok = FONT_CANDIDATES.filter(f => {
    if (embedded.indexOf(f) >= 0) return false;
    return bases.some(b => { cx.font = '72px "' + f + '", ' + b; return Math.abs(cx.measureText(S).width - bw[b]) > 0.6; });
  });
  _fontListCache = embedded.concat(ok);
  return _fontListCache;
}

/* ----- CP26(0.9.15):TW_THESIS 封面校徽自訂 ----- */
function applyTwThesisLogo(){
  normalizeTwThesisLogoChoice();
  const src = twthesisSelectedLogoSrc();
  document.querySelectorAll('img.twthesis-tp-logo,img.twthesis2-logo,img.twthesis-en-logo').forEach(im => {
    im.src = src;
    im.dataset.logoChoice = settings.twthesisLogoChoice;
  });
  applyTwThesisLogoScale();                    /* 標誌來源與視覺比例共用同一刷新入口 */
}
function importTwThesisLogo(file, done){
  if (!file || !/^image\//.test(file.type)){ toast(TT('請選擇圖片檔(JPG / PNG)','Please choose an image file (JPG / PNG)')); return; }
  const reader = new FileReader();
  reader.onload = () => {
    const url = String(reader.result);
    const finish = (dataUrl) => {
      if (dataUrl.length > 4 * 1024 * 1024){ toast(TT('圖片過大,無法儲存(請先縮小圖片)','Image too large to store — please shrink it first')); return; }
      settings.twthesisLogo = dataUrl;
      settings.twthesisLogoChoice = 'custom';
      applyTwThesisLogo(); persist();
      if (done) done();
      toast(TT('已更換封面校徽','Cover crest updated'));
    };
    if (file.type === 'image/svg+xml'){ finish(url); return; }   /* SVG 直接內嵌,不經畫布 */
    const img = new Image();
    img.onload = () => {
      const MAXW = 800;                      /* >300KB 或寬 >800px → 縮至寬 800、重編碼 PNG(保留透明度) */
      if (url.length <= 300 * 1024 && img.naturalWidth <= MAXW){ finish(url); return; }
      const scale = Math.min(1, MAXW / (img.naturalWidth || MAXW));
      const w = Math.max(1, Math.round((img.naturalWidth  || MAXW) * scale));
      const h = Math.max(1, Math.round((img.naturalHeight || MAXW) * scale));
      try {
        const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        cv.getContext('2d').drawImage(img, 0, 0, w, h);
        finish(cv.toDataURL('image/png'));
      } catch(_){ finish(url); }             /* 畫布失敗(如特殊 SVG)→ 退回原圖 */
    };
    img.onerror = () => toast(TT('無法讀取圖片','Could not read the image'));
    img.src = url;
  };
  reader.readAsDataURL(file);
}

