function exportHTML(){
  commitCurrent();
  const f = activeFile();
  const body = splitToBlocks(losslessActiveNormalized()).map(renderBlockHTML).join('\n');
  const html = `<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="UTF-8"><title>${escapeHtml(f.name)}</title><style>${MD_EXPORT_CSS}</style></head><body>\n${body}\n</body></html>`;
  download(f.name.replace(/\.(md|markdown|txt)$/i,'') + '.html', 'text/html', html);
  toast('已匯出 HTML');
}
/* CP14:穩妥本地儲存 —— 匯出「單一 HTML(圖片全內嵌 base64)」。
   一個可攜、免資料夾、免授權、不怕雲端驅逐/移動改名的本地檔:圖片位元組
   直接以 data URL 嵌入,file:// 雙擊即開、圖片必顯示。這是論文最穩的封存/交付格式。
   讀不到位元組的本機圖(未連結資料夾且未選過)→ 沿用 PDF 那套三鈕徵詢一次資料夾。 */
function fileToDataURL(file){
  return new Promise(res => {
    const r = new FileReader();
    r.onload = () => res(String(r.result));
    r.onerror = () => res(null);
    r.readAsDataURL(file);
  });
}
async function imgSrcToDataURL(src){
  if (/^data:/i.test(src)) return src;
  const key = String(src).replace(/^file:\/\//i, '').replace(/^\.\//, '').replace(/^\//, '');
  try { const file = await findFolderFile(key); if (file) return await fileToDataURL(file); } catch(_){}
  if (imgURLCache.has(key)){                                  // 記憶體中已解析的 blob
    try { return await fileToDataURL(await (await fetch(imgURLCache.get(key))).blob()); } catch(_){}
  }
  try { if (/^blob:/i.test(src)) return await fileToDataURL(await (await fetch(src)).blob()); } catch(_){}
  return null;
}
async function exportHTMLEmbedded(){
  commitCurrent();
  if (dirHandle)    await ensureReadPerm(dirHandle);
  if (imgDirHandle) await ensureReadPerm(imgDirHandle);
  const f = activeFile();
  const tmp = document.createElement('div');
  tmp.innerHTML = splitToBlocks(losslessActiveNormalized()).map(renderBlockHTML).join('\n');
  const imgs = [...tmp.querySelectorAll('img')];
  const embedAll = async () => {
    let missing = 0;
    for (const im of imgs){
      const src = im.getAttribute('src') || '';
      if (/^data:/i.test(src)) continue;
      const du = await imgSrcToDataURL(src);
      if (du){ im.setAttribute('src', du); im.removeAttribute('srcset'); }
      else if (!/^https?:/i.test(src)) missing++;             // 網路圖保留連結;本機圖缺 = 待補
    }
    return missing;
  };
  toast('正在內嵌圖片…');
  let missing = await embedAll();
  if (missing > 0){
    const act = await askPdfImgDir(missing);                  // 三鈕:選資料夾 / 略過 / 取消
    if (act === 'cancel'){ toast('已取消匯出'); return; }
    if (act === 'picked') missing = await embedAll();
  }
  const html = `<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="UTF-8"><title>${escapeHtml(f.name)}</title><style>${MD_EXPORT_CSS}</style></head><body>\n${tmp.innerHTML}\n</body></html>`;
  download(f.name.replace(/\.(md|markdown|txt)$/i,'') + '.embedded.html', 'text/html', html);
  toast(missing > 0 ? `已匯出單一檔(${missing} 張本機圖仍缺、以連結保留)` : '已匯出單一檔(圖片全內嵌,可攜)');
}

/* 拖放:圖片檔 → 存檔插入;.md → 開啟;網頁圖片 → 插入 URL(CP6 擴充) */
document.addEventListener('dragover', e => e.preventDefault());
document.addEventListener('drop', e => {
  e.preventDefault();
  const list = [...(e.dataTransfer.files || [])];
  const imgs = list.filter(f => /^image\//.test(f.type));
  if (imgs.length){
    /* 游標移到放開的位置(取不到則附加文件尾) */
    const r = document.caretRangeFromPoint && document.caretRangeFromPoint(e.clientX, e.clientY);
    if (r && editor.contains(r.startContainer)){
      const s = getSelection(); s.removeAllRanges(); s.addRange(r);
    }
    handleImageFiles(imgs, '拖入的圖片');
    return;
  }
  const file = list[0];
  if (file && /\.(md|markdown|txt)$/i.test(file.name)){
    const reader = new FileReader();
    reader.onload = () => {
      commitCurrent();
      const f = { id: uid(), name: file.name, content: String(reader.result) };
      files.push(f); switchFile(f.id);
      toast('已開啟 ' + file.name);
    };
    reader.readAsText(file);
    return;
  }
  const uri = (e.dataTransfer.getData('text/uri-list') || '').split('\n')[0].trim();
  if (/^https?:\/\/\S+\.(png|jpe?g|gif|webp|svg|bmp)(\?\S*)?$/i.test(uri))
    insertImageMD(uri, '網頁圖片');
});

