/* 標題列拖曳 */
(() => {
  const head = $('#pe-head');
  let sx = 0, sy = 0, ox = 0, oy = 0, dragging = false;
  head.addEventListener('mousedown', e => {
    dragging = true; sx = e.clientX; sy = e.clientY;
    const p = pePanel();
    ox = parseFloat(p.style.left) || 0; oy = parseFloat(p.style.top) || 0;
    e.preventDefault();
  });
  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    const p = pePanel();
    p.style.left = Math.max(4, Math.min(ox + e.clientX - sx, innerWidth - 80)) + 'px';
    p.style.top  = Math.max(4, Math.min(oy + e.clientY - sy, innerHeight - 40)) + 'px';
  });
  document.addEventListener('mouseup', () => dragging = false);
})();
/* 點面板外(且不在編輯區內)→ 提交關閉;編輯區內的點擊由下方路由接手 */
document.addEventListener('mousedown', e => {
  if (peIndex < 0) return;
  if (e.target.closest && (e.target.closest('#pe-panel') || e.target.closest('#img-bar'))) return;
  if (editor.contains(e.target)) return;
  finishPaperEdit(true);
}, true);

