  const baseW = Math.max(1, scroller.clientWidth || scroller.getBoundingClientRect().width || 1);
  surface.style.width = baseW + 'px';
  const stageW = Math.max(baseW, baseW * z);
  surface.style.left = ((stageW - baseW) / 2) + 'px';
