function shortcutReferenceBody(platform){
  const groups=[], seen={};
  COMMANDS.forEach(c=>{
    if (c.hide || !c.group) return;
    if (!seen[c.group]){ seen[c.group]=[]; groups.push([c.group,seen[c.group]]); }
    seen[c.group].push(c);
  });
  const commandHtml=groups.map(([group,commands])=>`<section class="shortcut-group">
    <h3 class="shortcut-group-title">${escapeHtml(TL(group))}</h3>
    ${commands.map(c=>`<div class="shortcut-command-row"><span class="shortcut-command-label">${escapeHtml(TL(c.label))}</span><span class="shortcut-keys">${shortcutKbdHTML(shortcutKeysForCommand(c,platform))}</span></div>`).join('')}
  </section>`).join('');
  const contextHtml=shortcutContextRows(platform).map(row=>`<div class="shortcut-context-row">
    <span class="shortcut-context-copy"><span class="shortcut-context-name">${escapeHtml(row[0])}</span><span class="shortcut-context-desc">${escapeHtml(row[1])}</span></span>
    <span class="shortcut-keys">${shortcutKbdHTML(String(row[2]).split(/\s+\/\s+/))}</span>
  </div>`).join('');
  const note=isEN()
    ? `The selected platform changes only this reference display; it does not remap the program. “Menu only” means the current browser-safe command registry has no reliable shortcut on that platform. Browser-reserved keys such as New/Open may still be intercepted. Markdown quick input includes <b># heading</b>, <b>- list</b>, <b>1. numbered</b>, <b>&gt; quote</b>, <b>- [ ] task</b>, a code fence or <b>$$</b> followed by Enter, <b>---</b>, <b>==highlight==</b>, and <b>$E=mc^2$</b>.`
    : `上方系統切換只改變這份速查表的顯示，不會重新綁定程式快捷鍵。「僅選單」代表目前瀏覽器安全範圍內沒有可靠的該系統按鍵；新增／開啟等保留鍵仍可能被瀏覽器攔截。Markdown 快速輸入包含 <b># 標題</b>、<b>- 清單</b>、<b>1. 編號</b>、<b>&gt; 引言</b>、<b>- [ ] 任務</b>、程式碼圍欄或 <b>$$</b> 後按 Enter、<b>---</b>、<b>==螢光==</b> 與 <b>$E=mc^2$</b>。`;
  return `<div class="shortcut-command-grid">${commandHtml}</div>
    <h3 class="shortcut-context-title">${TT('情境操作','Context controls')}</h3>
    <div class="shortcut-context-list">${contextHtml}</div>
    <div class="shortcut-note">${note}</div>`;
}
function renderShortcutReference(){
  $$('.shortcut-platform-btn').forEach(btn=>{
    const active=btn.dataset.platform===shortcutPlatform;
    btn.setAttribute('aria-selected',active?'true':'false');
    btn.tabIndex=active?0:-1;
  });
  const body=$('#shortcut-content');
  if (body) body.innerHTML=shortcutReferenceBody(shortcutPlatform);
}
function showShortcuts(){
  const tabs=Object.entries(SHORTCUT_PLATFORM_LABELS).map(([id,label])=>`<button class="shortcut-platform-btn" type="button" role="tab" data-platform="${id}" aria-selected="false">${label}</button>`).join('');
  showModal(`<div class="shortcut-shell">
    <header class="shortcut-head"><div class="shortcut-title-wrap"><h2>${TT('Markdown 與快捷鍵速查','Markdown & Shortcut Reference')}</h2><p class="shortcut-subtitle">${TT('主指令取自目前程式 Registry；下方另列只在特定編輯情境生效的按鍵。','Main commands come from the live registry; context-only keys are listed separately below.')}</p></div><div class="shortcut-platform-switch" role="tablist" aria-label="${TT('快捷鍵作業系統','Shortcut operating system')}">${tabs}</div></header>
    <div id="shortcut-content" class="shortcut-content"></div>
  </div>`);
  $('#modal').classList.add('shortcut-modal');
  $$('.shortcut-platform-btn').forEach(btn=>{
    btn.addEventListener('click',()=>{ shortcutPlatform=btn.dataset.platform; renderShortcutReference(); });
    btn.addEventListener('keydown',e=>{
      if (!['ArrowLeft','ArrowRight','Home','End'].includes(e.key)) return;
      e.preventDefault();
      const order=['mac','windows','linux']; let i=order.indexOf(shortcutPlatform);
      if (e.key==='Home') i=0; else if (e.key==='End') i=order.length-1; else i=(i+(e.key==='ArrowRight'?1:-1)+order.length)%order.length;
      shortcutPlatform=order[i]; renderShortcutReference();
      const next=$(`.shortcut-platform-btn[data-platform="${shortcutPlatform}"]`); if(next) next.focus();
    });
  });
  renderShortcutReference();
}

window.__CP141_SHORTCUT_REFERENCE__ = Object.freeze({
  platforms:Object.keys(SHORTCUT_PLATFORM_LABELS), commandCount:COMMANDS.filter(c=>!c.hide&&c.group).length,
  contextCount:shortcutContextRows('mac').length, sigLabel:shortcutSigLabel, commandKeys:shortcutKeysForCommand
});

/* ---------- 時鐘 ---------- */
function tickClock(){
  const d = new Date();
  const hm = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  if (isEN()){
    const wd = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getDay()];
    const mo = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()];
    $('#mb-clock').textContent = `${wd} ${mo} ${d.getDate()}  ${hm}`;
  } else {
    const wd = ['日','一','二','三','四','五','六'][d.getDay()];
    $('#mb-clock').textContent = `${d.getMonth()+1}月${d.getDate()}日 週${wd} ${hm}`;
  }
}
setInterval(tickClock, 15000);

