  if(host)return host;
  host=document.createElement('section');host.id='revtex-wysiwyg';host.setAttribute('aria-label',TT('REVTeX 所見即所得頁面','REVTeX WYSIWYG pages'));
  host.innerHTML='<div class="rvx-live-toolbar" contenteditable="false"><span class="rvx-live-status">'+TT('逐頁所見即所得','Page WYSIWYG')+'</span><button type="button" data-rvx-live-layout="one">'+TT('單欄','One column')+'</button><button type="button" data-rvx-live-layout="two">'+TT('雙欄','Two columns')+'</button><button type="button" data-rvx-live-settings>'+TT('版面設定','Layout settings')+'</button><span class="rvx-live-layout"></span></div><div class="rvx-live-pages"></div>';
