    let off=0;
    try{
      const cp=paperClientPoint(e.clientX,e.clientY);
      if(cp&&unit.contains(cp.node)){const r=document.createRange();r.selectNodeContents(unit);r.setEnd(cp.node,cp.off);off=visibleToRaw(blocks[i]||'',r.toString().length);}
    }catch(_){off=0;}
