    if((cap||mdCap)&&normal.length){let j=normal.length-1;while(j>=0&&!String(normal[j].node.innerText||'').trim()&&!normal[j].node.querySelector('table,figure,.md-math-block'))j--;const prev=j>=0?normal[j]:null,tbl=prev&&prev.node.querySelector('table.md-table');if(tbl){normal.splice(j,normal.length-j);const wrap=document.createElement('div');wrap.className='rvx-live-block rvx-table-group';wrap.dataset.rvxSourceIndex=String(prev.index);const caption=clone;if(mdCap)caption.classList.add('revtex-table-caption-wrap');wrap.appendChild(caption);wrap.appendChild(prev.node);normal.push({node:wrap,wide:false,float:true,index:prev.index});return;}}
